CREATE TABLE aoo_rank_season(id VARCHAR(64) PRIMARY KEY,period_type ENUM('DAILY','WEEKLY','SEASON') NOT NULL,starts_at TIMESTAMP(6) NOT NULL,ends_at TIMESTAMP(6) NOT NULL,state ENUM('ACTIVE','FROZEN','CLOSED') NOT NULL,INDEX ix_rank_season_window(period_type,state,starts_at,ends_at));
CREATE TABLE aoo_rank_score(season_id VARCHAR(64) NOT NULL,player_id BIGINT NOT NULL,score BIGINT NOT NULL,updated_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(season_id,player_id),INDEX ix_rank_page(season_id,score DESC,player_id ASC),CONSTRAINT fk_rank_season FOREIGN KEY(season_id) REFERENCES aoo_rank_season(id));
CREATE TABLE aoo_achievement_definition(code VARCHAR(64) PRIMARY KEY,target_value BIGINT NOT NULL,reward_kind ENUM('CURRENCY','ITEM') NOT NULL,reward_code VARCHAR(64) NOT NULL,reward_amount BIGINT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE aoo_achievement_progress(player_id BIGINT NOT NULL,achievement_code VARCHAR(64) NOT NULL,progress BIGINT NOT NULL,updated_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(player_id,achievement_code),CONSTRAINT fk_progress_definition FOREIGN KEY(achievement_code) REFERENCES aoo_achievement_definition(code));
CREATE TABLE aoo_achievement_claim(player_id BIGINT NOT NULL,achievement_code VARCHAR(64) NOT NULL,business_id VARCHAR(160) NOT NULL UNIQUE,claimed_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(player_id,achievement_code));
